'use strict';

// Tests for the release text generated by scripts/release-notes.js.
// Run with: node --test tests/release.test.js

const test = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const { notes } = require('../scripts/release-notes.js');

const sha = (buf) =>
  crypto.createHash('sha256').update(buf).digest('hex');

test('the release contains the English description, news and checksums', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'capri-release-'));

  try {
    fs.writeFileSync(path.join(dir, 'Capri-Setup-1.2.3-ia32.exe'), 'thirty-two');
    fs.writeFileSync(path.join(dir, 'Capri-Setup-1.2.3-x64.exe'), 'sixty-four');
    fs.writeFileSync(path.join(dir, 'Capri-1.2.3-arm64.dmg'), 'mac');
    fs.writeFileSync(path.join(dir, 'Capri-1.2.3-x86_64.AppImage'), 'linux');
    fs.writeFileSync(path.join(dir, 'latest.yml'), 'not an installer');

    const text = notes(dir, {
      version: '1.2.3',
      repo: 'me/capri',
      news: '- First change\n- Second change\n'
    });

    assert.match(text, /^## Capri 1\.2\.3/);

    assert.ok(text.includes(
      'Capri is a living desktop companion that watches Claude Code, Codex, and Antigravity, chats through any AI model, gets angry, laughs, sees your screen, listens, and remembers you.'
    ));

    assert.ok(text.includes(
      'Windows, macOS, and Linux packages are built separately. Installation methods and available system features depend on the platform.'
    ));

    assert.ok(text.includes('SmartScreen'));

    assert.match(text, /### What's new\n\n- First change\n- Second change/);
    assert.match(text, /### SHA-256 checksums/);

    assert.ok(text.includes(`${sha('sixty-four')}  Capri-Setup-1.2.3-x64.exe`));
    assert.ok(text.includes(`${sha('thirty-two')}  Capri-Setup-1.2.3-ia32.exe`));
    assert.ok(text.includes(`${sha('mac')}  Capri-1.2.3-arm64.dmg`));
    assert.ok(text.includes(`${sha('linux')}  Capri-1.2.3-x86_64.AppImage`));

    assert.ok(!text.includes('latest.yml'));
    assert.ok(!text.includes('Getting started'));
    assert.ok(!text.includes('README'));
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test('no news means no What’s new heading, and no artifacts is an error', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'capri-release-'));

  try {
    assert.throws(
      () => notes(dir, {
        version: '1',
        repo: '',
        news: ''
      }),
      /no Capri release artifacts/i
    );

    fs.writeFileSync(path.join(dir, 'Capri-Setup-1-x64.exe'), 'x');

    const text = notes(dir, {
      version: '1',
      repo: '',
      news: '  \n'
    });

    assert.ok(!text.includes("What's new"));
    assert.ok(!text.includes('Getting started'));
    assert.ok(!text.includes('README'));
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test('the uninstaller asks whether what she downloaded goes too, and never on an update or a silent uninstall', () => {
  const pkg = JSON.parse(
    fs.readFileSync(
      path.join(__dirname, '..', 'package.json'),
      'utf8'
    )
  );

  assert.equal(
    pkg.build.nsis.include,
    'build/installer.nsh',
    'the installer script is part of the build'
  );

  const raw = fs.readFileSync(
    path.join(__dirname, '..', pkg.build.nsis.include)
  );

  assert.deepEqual(
    [...raw.subarray(0, 3)],
    [0xef, 0xbb, 0xbf],
    'a UTF-8 file with a byte-order mark'
  );

  const nsh = raw.toString('utf8');

  assert.match(nsh, /!macro customUnInstall/);

  assert.match(
    nsh,
    /\$\{ifNot\} \$\{isUpdated\}/i,
    'an update asks nothing and removes nothing'
  );

  assert.match(
    nsh,
    /MessageBox MB_YESNO[^\n]*Удалить также[^\n]*Also delete/,
    'the question is available in both languages'
  );

  assert.match(
    nsh,
    /\$\{GetOptions\} \$R0 "\/S"/,
    'a silent uninstall is told apart'
  );

  assert.ok(
    (nsh.match(/--remove-everything/g) || []).length >= 3,
    'the remove-everything option is handled in all required places'
  );

  assert.match(
    nsh,
    /RMDir \/r "\$APPDATA\\\$\{APP_FILENAME\}"/,
    'the app data folder is removed when requested'
  );

  // The app handles the flag before anything else starts.
  const main = fs.readFileSync(
    path.join(__dirname, '..', 'src', 'main', 'main.js'),
    'utf8'
  );

  assert.ok(
    main.indexOf("argv.includes('--remove-everything')") <
      main.indexOf('applyRender();\n  if (!app.requestSingleInstanceLock'),
    'the flag is handled before the one-instance lock'
  );

  assert.match(
    nsh,
    /"\$INSTDIR\\\$\{APP_EXECUTABLE_FILENAME\}" --remove-everything/,
    'the app executable is launched by the uninstaller'
  );

  assert.match(
    nsh,
    /\$\{GetOptions\} \$R0 "--remove-everything"/,
    'silent uninstall supports explicit removal of downloaded data'
  );
});

test('the distribution config exposes supported packages and signed update release targets', () => {
  const pkg = JSON.parse(
    fs.readFileSync(
      path.join(__dirname, '..', 'package.json'),
      'utf8'
    )
  );

  assert.deepEqual(
    pkg.build.linux.target,
    ['AppImage', 'deb']
  );

  assert.equal(
    pkg.scripts['dist:mac:arm64'],
    'electron-builder --mac --arm64'
  );

  assert.equal(
    pkg.scripts['dist:mac:x64'],
    'electron-builder --mac --x64'
  );

  assert.equal(
    pkg.build.mac.artifactName,
    'Capri-${version}-${arch}-mac.${ext}'
  );

  assert.equal(
    pkg.build.nsis.artifactName,
    'Capri-Setup-${version}-${arch}.${ext}'
  );

  assert.equal(
    pkg.dependencies['electron-updater'],
    undefined,
    'the custom signed updater does not depend on electron-updater'
  );

  const updater = fs.readFileSync(
    path.join(__dirname, '..', 'src/main/update-manager.js'),
    'utf8'
  );

  assert.match(
    updater,
    /api\.github\.com\/repos\/jsaber-irl\/capri-desktop\/releases\/latest/
  );

  assert.match(
    updater,
    /crypto\.verify\(null, raw, publicKey, signature\)/
  );

  assert.match(
    updater,
    /createHash\('sha512'\)/
  );

  const workflow = fs.readFileSync(
    path.join(__dirname, '..', '.github/workflows/release.yml'),
    'utf8'
  );

  assert.match(workflow, /CAPRI_UPDATE_PRIVATE_KEY/);
  assert.match(workflow, /dist:mac:arm64/);
  assert.match(workflow, /dist:mac:x64/);
  assert.match(workflow, /create-update-manifest\.js/);
});
